package gadomancymodern.node;
import gadomancymodern.Gadomancy;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.*;
import tc4revival.aspect.*;
import tc4revival.content.*;
public class ExtendedNodeEntity extends AuraNodeBlockEntity {
    public String extension="";public GrowingSaturation growth=new GrowingSaturation();public int growingTicks;public BlockPos prey;public GrowingVortexExplosion explosion;
    public ExtendedNodeEntity(BlockPos pos,BlockState state){super(Gadomancy.EXTENDED_NODE_BE.get(),pos,state);}
    public boolean growing(){return extension.equals("gadomancy:growing");}
    @Override public void tick(){super.tick();growingTicks++;if(isRemoved())return;if(level.isClientSide){if(growing())feedEntities(false);return;}if(explosion!=null){explosion.tick();if(explosion.finished())explosion=null;}if(!growing())return;feedEntities(true);hunt();if(level.getDifficulty()!=net.minecraft.world.Difficulty.PEACEFUL&&growingTicks%8==0)for(var living:level.getEntitiesOfClass(LivingEntity.class,new AABB(worldPosition).inflate(6))){if(!living.isAlive()||living.isInvulnerable()||living instanceof Player p&&p.getAbilities().instabuild||!growth.zap(level.random.nextInt(160000)))continue;discover("growing_aggression",6);living.hurt(level.damageSources().magic(),growth.damage());level.playSound(null,worldPosition,TCSounds.ZAP.get(),net.minecraft.sounds.SoundSource.BLOCKS,.8f,1);NodeVisualNetwork.bolt((ServerLevel)level,worldPosition.getCenter(),living.position().add(0,living.getBbHeight(),0),0);}}
    protected void feedEntities(boolean server){var center=worldPosition.getCenter();for(var entity:level.getEntities((Entity)null,new AABB(worldPosition).inflate(15),e->e instanceof AspectOrbEntity||e instanceof WispEntity||e instanceof ItemEntity item&&(item.getItem().getItem() instanceof WispEssenceItem||item.getItem().getItem() instanceof EssenceCrystalItem||item.getItem().getItem() instanceof ManaBeanItem))){if(entity.isAlive()&&!entity.isInvulnerable()&&entity.position().distanceTo(center)<.5&&server){Aspect aspect=null;String kind="";if(entity instanceof AspectOrbEntity orb){aspect=orb.aspect();kind="aspect_orb";}else if(entity instanceof WispEntity wisp){aspect=TCAspects.catalog().find(wisp.aspectTag()).orElse(null);kind="wisp";}else if(entity instanceof ItemEntity item&&item.getItem().getItem() instanceof StoredAspectItem stored){var values=stored.storedAspects(item.getItem());aspect=values.isEmpty()?null:values.aspects().get(0);kind=item.getItem().getItem() instanceof WispEssenceItem?"wisp_essence":item.getItem().getItem() instanceof EssenceCrystalItem?"crystal_essence":"mana_bean";}if(aspect!=null){if(aspects().amount(aspect)<base().amount(aspect))addCharge(aspect,1);else if(base().amount(aspect)<1000000&&growth.accepts(aspect.tag(),level.random.nextFloat())){boolean trigger=growth.fed(aspect.tag(),aspect.isPrimal(),kind);var values=permanentBase();values.add(aspect,1);editPermanent(values,permanentType(),permanentModifier());discover("growing_growth",6);if(trigger&&explosion==null)explosion=new GrowingVortexExplosion(this);}}entity.discard();sync();continue;}var delta=center.subtract(entity.position()).scale(1.0/15);double distance=delta.length(),strength=1-distance;if(distance<1e-8||strength<=0)continue;strength*=strength;entity.setDeltaMovement(entity.getDeltaMovement().add(delta.x/distance*strength*.15,delta.y/distance*strength*.25,delta.z/distance*strength*.15));entity.hasImpulse=true;}}
    protected void hunt(){if(prey==null){var pos=worldPosition.offset(level.random.nextInt(8)-level.random.nextInt(8),level.random.nextInt(8)-level.random.nextInt(8),level.random.nextInt(8)-level.random.nextInt(8));if(!pos.equals(worldPosition)&&level.hasChunkAt(pos)&&level.getBlockEntity(pos) instanceof AuraNodeBlockEntity node&&permanentBase().total()>=node.permanentBase().total()){prey=pos;node.sync();sync();}return;}if(growingTicks%3!=0)return;if(!level.hasChunkAt(prey)||!(level.getBlockEntity(prey) instanceof AuraNodeBlockEntity victim)||victim.isRemoved()){prey=null;return;}var base=victim.permanentBase();if(base.isEmpty()){level.removeBlock(prey,false);prey=null;return;}var aspect=base.aspects().get(level.random.nextInt(base.size()));if(base.amount(aspect)<=0){base.remove(aspect);if(base.isEmpty()){level.removeBlock(prey,false);prey=null;}else victim.editPermanent(base,victim.permanentType(),victim.permanentModifier());return;}base.reduce(aspect,1);victim.take(aspect,1);victim.editPermanent(base,victim.permanentType(),victim.permanentModifier());var from=prey.getCenter();var orb=new AspectOrbEntity(level,from.x,from.y,from.z,aspect,1);orb.setDeltaMovement(worldPosition.getCenter().subtract(from).normalize());level.addFreshEntity(orb);discover("growing_attack",16);NodeVisualNetwork.bolt((ServerLevel)level,worldPosition.getCenter(),from,0);NodeVisualNetwork.absorb((ServerLevel)level,prey,worldPosition.getCenter(),7);sync();}
    public void discover(String research,double range){if(!(level instanceof ServerLevel server))return;String key="gadomancy:"+research;for(var player:level.getEntitiesOfClass(net.minecraft.server.level.ServerPlayer.class,new AABB(worldPosition).inflate(range))){var snapshot=tc4revival.research.KnowledgeSavedData.get(server.getServer()).snapshot(player.getUUID());if(snapshot.isPresent()&&snapshot.get().researchMarkers().contains(key))continue;if(snapshot.isPresent()&&tc4revival.research.ResearchCatalogs.catalog().find(key).isPresent()&&tc4revival.research.ResearchCatalogs.rules().prerequisites(snapshot.get(),key))thaumcraft.api.ThaumcraftApiHelper.completeResearch(player,key);}}
    @Override protected void saveAdditional(CompoundTag tag){super.saveAdditional(tag);var extra=new CompoundTag();extra.putString("Type",extension);extra.put("Growth",growth.save());tag.put("Gadomancy",extra);}
    @Override public void load(CompoundTag tag){super.load(tag);var extra=tag.getCompound("Gadomancy");extension=extra.getString("Type");growth=new GrowingSaturation();growth.load(extra.getCompound("Growth"));prey=null;explosion=null;}
    public static ExtendedNodeEntity convert(ServerLevel level,BlockPos pos){if(level.getBlockEntity(pos) instanceof ExtendedNodeEntity existing)return existing;if(!(level.getBlockEntity(pos) instanceof AuraNodeBlockEntity old))return null;var tag=old.saveWithoutMetadata();var state=Gadomancy.EXTENDED_NODE.get().defaultBlockState().setValue(AuraNodeBlock.WATERLOGGED,level.getFluidState(pos).is(net.minecraft.tags.FluidTags.WATER));if(!level.setBlock(pos,state,3))return null;if(!(level.getBlockEntity(pos) instanceof ExtendedNodeEntity node))return null;node.load(tag);node.sync();return node;}
}
